# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, E, R, U = "Lucas", "Amparo", "Ernesto", "Ramón", "Maru"
D = [
("#", "Escena 1 · 9:00 · Agencia aduanal, centro de Monterrey", "장면 1 · 오전 9시 · 몬테레이 도심의 관세사 사무소"),
(None, "Jueves 17 de abril. Jueves Santo. El centro de Monterrey está medio vacío: muchas oficinas han cerrado hasta el lunes. En el tercer piso de un edificio de los años setenta, una placa de latón: «Salinas y Asociados · Agencia Aduanal · Monterrey – Altamira». Iván los ha dejado en la puerta.", "4월 17일 목요일, 성목요일. 몬테레이 도심은 반쯤 비어 있다. 많은 사무실이 월요일까지 문을 닫았다. 1970년대 건물 4층에 놋쇠 명판이 붙어 있다. '살리나스 앤드 어소시에이츠 · 관세사 사무소 · 몬테레이–알타미라'. 이반이 두 사람을 문 앞에 내려 주었다."),
(U, "Buenos días, bienvenidos. ¿Ustedes son los de España? El licenciado los está esperando.", "안녕하세요, 어서 오세요. 스페인에서 오신 분들이죠? 변호사님이 기다리고 계세요."),
(A, "Buenos días. Sí: Amparo Albalat y Lucas Ferrer, de Cerámicas Albalat.", "안녕하세요. 네, 세라미카스 알발라트의 암파로 알발라트와 루카스 페레르예요."),
(U, "Mucho gusto. Yo soy Maru. ¿Les ofrezco un cafecito? ¿Un agüita?", "반갑습니다. 저는 마루예요. 커피 한 잔 드릴까요? 물이라도?"),
(L, "Un café, por favor. Solo, sin azúcar.", "커피 주세요. 블랙으로, 설탕 없이요."),
(U, "¿Solo? Ah, un americano, ¿verdad? Ahorita se lo traigo.", "솔로요? 아, 아메리카노 말씀이시죠? 지금 바로 가져다드릴게요."),
(A, "(en voz baja) Apunta otra: aquí un café solo es un americano.", "(작은 목소리로) 하나 더 적어 둬요. 여기선 '카페 솔로'가 아메리카노예요."),
(L, "(en voz baja) Y aquí «ahorita» por fin significa «ahora mismo». Ya es un avance.", "(작은 목소리로) 그리고 여기선 '아오리타'가 드디어 '지금 당장'이라는 뜻이네요. 그것만 해도 발전이에요."),
(None, "Se abre la puerta del despacho. Ernesto Salinas, unos sesenta años, bigote gris y guayabera blanca, sale con los brazos abiertos.", "사무실 문이 열린다. 예순쯤 되어 보이는 에르네스토 살리나스가 회색 콧수염에 흰 과야베라 셔츠 차림으로 두 팔을 벌리며 나온다."),
(E, "¡El famoso licenciado Ferrer! Por fin le veo la cara. Por teléfono me lo imaginaba más alto.", "그 유명한 페레르 선생! 드디어 얼굴을 보네요. 전화로는 키가 더 클 줄 알았어요."),
(L, "(ríe) Y yo a usted, con corbata. Licenciado Salinas, es un placer. Le debo una.", "(웃으며) 저는 넥타이를 매셨을 줄 알았어요. 살리나스 선생님, 반갑습니다. 신세를 졌어요."),
(E, "¿Una? Me debe unas muestras con una factura de valor cero que casi se quedan a vivir en la aduana. «Valor cero», licenciado. En México nada vale cero. Pero ya pasó. Pásenle, pásenle.", "하나요? 가액 0원짜리 송장을 달고 와서 세관에 눌러살 뻔한 샘플 신세를 지셨죠. '가액 0'이라니요, 선생님. 멕시코에선 공짜인 건 없어요. 하지만 지난 일이에요. 들어오세요, 들어오세요."),
(A, "Gracias por recibirnos hoy. Iván nos ha dicho que es Jueves Santo y que media ciudad se ha ido a la playa.", "오늘 만나 주셔서 감사해요. 이반이 성목요일이라 도시 절반이 바닷가로 떠났다고 하더라고요."),
(E, "La otra media se fue a Santiago o a la Huasteca. Yo me quedo: las aduanas no cierran, y los barcos no saben de Semana Santa.", "나머지 절반은 산티아고나 우아스테카로 갔죠. 저는 남아요. 세관은 쉬지 않고, 배는 부활절 주간을 모르거든요."),
(L, "Pues gracias por partida doble. Venimos a que nos explique qué le pasa a nuestra baldosa desde que toca México hasta que llega a la bodega de Alejandra.", "그럼 두 배로 감사드려요. 저희 타일이 멕시코 땅에 닿아서 알레한드라의 창고에 도착할 때까지 무슨 일이 일어나는지 배우러 왔어요."),
(E, "Muy bien. Primero, díganme qué venden y en qué condiciones. Lo demás lo ponemos en el pizarrón.", "좋아요. 먼저 뭘, 어떤 조건으로 파시는지 말씀해 주세요. 나머지는 칠판에 적어 가며 하죠."),
(L, "Dos torres en San Pedro: cuarenta mil metros cuadrados de porcelánico. Precio DAP Monterrey: quince euros con noventa y cuatro el metro.", "산페드로의 아파트 두 동이요. 자기질 타일 4만㎡. 가격은 DAP 몬테레이 조건으로 ㎡당 15유로 94센트예요."),
(E, "DAP Monterrey. O sea, ustedes pagan el barco hasta Altamira y el tráiler hasta aquí. Pero sin despachar.", "DAP 몬테레이라. 그러니까 알타미라까지 배삯과 여기까지 트레일러 운송비는 그쪽이 내고, 통관은 안 한 상태로군요."),
(A, "Exacto. El despacho de importación es cosa del comprador. Es decir, de Alejandra. Es decir, de usted.", "맞아요. 수입 통관은 구매자 몫이에요. 그러니까 알레한드라 몫이고, 결국 선생님 몫이죠."),
(E, "De mi agencia, sí. Mi gente de Altamira hace el pedimento en el puerto, y el tráiler sigue su camino ya nacionalizado.", "제 사무소 몫이죠. 알타미라에 있는 우리 직원들이 항구에서 수입 신고서를 처리하고, 트레일러는 '국산화'된 상태로 계속 달려요."),
(L, "¿Nacionalizado?", "국산화요?"),
(E, "Que la mercancía ya es «nacional»: ha pagado lo que tenía que pagar y puede circular. Antes de eso es mercancía extranjera, cuyo dueño todavía no puede ni tocarla.", "화물이 이제 '국내 화물'이 됐다는 뜻이에요. 낼 걸 다 내서 돌아다닐 수 있다는 거죠. 그 전에는 외국 화물이라, 주인조차 손댈 수 없어요."),
(L, "Entendido. Entonces, ¿qué se paga para nacionalizar una baldosa?", "알겠어요. 그럼 타일 한 장을 국산화하려면 뭘 내야 하죠?"),
(E, "Cuatro cosas. Primero, el arancel. Luego, un derecho de trámite, el DTA, que es chiquito. Después, el IVA. Y por último, mis honorarios, que son los más bonitos.", "네 가지예요. 첫째, 관세. 그다음 통관 수수료인 DTA, 이건 아주 작아요. 그 뒤에 부가가치세. 마지막으로 제 수수료, 이게 제일 예쁘죠."),
(A, "Empecemos por el arancel. Es lo que más nos preocupa.", "관세부터 시작하죠. 그게 제일 걱정이에요."),
(E, "Depende de la fracción arancelaria, el código que le toca a su producto. Para el porcelánico hay una fracción concreta; mañana se la confirmo por escrito.", "관세 품목 분류, 그러니까 제품에 해당하는 코드에 달렸어요. 자기질 타일엔 정해진 분류가 있고, 내일 서면으로 확인해 드릴게요."),
(L, "¿Y con el acuerdo entre México y la Unión Europea?", "멕시코와 유럽연합의 협정은요?"),
(E, "Ahí está la clave. Si la factura trae la declaración de origen bien hecha, ustedes entran con preferencia arancelaria. Y con preferencia, el arancel no les va a mover el número.", "바로 그게 핵심이에요. 송장에 원산지 신고가 제대로 들어가 있으면 특혜관세로 들어와요. 특혜를 받으면 관세가 숫자를 흔들지 못하죠."),
(A, "¿Y si la declaración viene mal?", "신고가 잘못 들어오면요?"),
(E, "Entonces pagan el arancel completo, y doña Alejandra me llama a mí a las tres de la mañana. Por eso tiene que venir bien. ¿Quién les hace las facturas?", "그럼 관세를 전액 내고, 알레한드라 여사는 새벽 3시에 저한테 전화를 하죠. 그러니까 제대로 와야 해요. 송장은 누가 작성하나요?"),
(L, "Administración, en Onda. Ramón, nuestro director financiero, se encarga.", "온다의 관리팀이요. 재무이사 라몬이 맡고 있어요."),
(E, "Pues que Ramón me mande un borrador de factura antes del primer embarque. Un borrador, no la buena. Así lo revisamos sin prisa.", "그럼 라몬 씨더러 첫 선적 전에 송장 초안을 보내 달라고 하세요. 정식 송장 말고 초안이요. 그래야 서두르지 않고 검토하죠."),
(A, "Lo apunto: borrador de factura con declaración de origen, antes de embarcar.", "적어 둘게요. 원산지 신고가 들어간 송장 초안, 선적 전에."),
(E, "Ahora, el IVA. Aquí es el dieciséis por ciento, y se calcula sobre el valor en aduana, más el arancel y el DTA.", "이제 부가가치세. 여기선 16%이고, 과세가격에 관세와 DTA를 더한 금액에 매겨요."),
(L, "¿El dieciséis por ciento? Eso sí que es un número que asusta.", "16%요? 그건 정말 겁나는 숫자네요."),
(E, "Asusta, pero no muerde. Doña Alejandra lo paga en la aduana y luego lo acredita en su declaración. No es un costo: es dinero que le presta al gobierno unas semanas.", "겁나긴 해도 물지는 않아요. 알레한드라 여사가 세관에서 내고 나중에 신고할 때 공제받아요. 비용이 아니라, 몇 주 동안 정부에 빌려주는 돈이에요."),
(A, "Como el IVA soportado en España. Se deduce.", "스페인의 매입 부가세랑 같네요. 공제되는 거요."),
(E, "Igualito, nomás que con otro nombre. Aquí decimos «IVA acreditable».", "똑같아요, 이름만 다를 뿐이죠. 여기선 '공제 가능 부가세'라고 해요."),
(L, "Entonces, para compararnos con los italianos, el IVA no cuenta.", "그럼 이탈리아 업체와 비교할 때는 부가세는 빼도 되겠네요."),
(E, "Para el costo, no. Para la caja, sí. Si doña Alejandra trae treinta contenedores en un mes, ese día tiene que tener el dinero del IVA.", "원가로는 빼도 되죠. 자금 흐름으로는 아니에요. 알레한드라 여사가 한 달에 컨테이너 서른 개를 들여오면, 그날 부가세 낼 돈은 있어야 해요."),

("#", "Escena 2 · 11:00 · Sala de juntas — videollamada con Onda", "장면 2 · 오전 11시 · 회의실 — 온다와 화상 통화"),
(None, "En la pantalla aparece Ramón, en su despacho de Onda. Detrás de él, la ventana ya está oscura: allí son las siete de la tarde. Maru deja una charola con pan dulce.", "화면에 온다 사무실의 라몬이 나타난다. 그의 뒤 창문은 벌써 어둡다. 그곳은 저녁 7시다. 마루가 단빵이 담긴 쟁반을 놓고 간다."),
(R, "Buenas tardes desde el futuro. Aquí ya es de noche, por si os interesa.", "미래에서 인사드려요. 여긴 벌써 밤이에요, 궁금하실까 봐."),
(E, "Buenos días desde el pasado, licenciado. Ernesto Salinas, para servirle.", "과거에서 인사드립니다, 선생님. 에르네스토 살리나스입니다. 잘 부탁드려요."),
(R, "Encantado, Ernesto. Lucas dice que usted salvó las muestras en marzo. Gracias.", "반갑습니다, 에르네스토. 루카스 말로는 3월에 샘플을 구해 주셨다고요. 고맙습니다."),
(E, "Lo que salvé fue la paciencia de doña Alejandra. ¿Hacemos números?", "제가 구한 건 알레한드라 여사의 인내심이죠. 숫자를 맞춰 볼까요?"),
(R, "Para eso sigo despierto. Lucas, ¿compartes tú la hoja?", "그러려고 아직 안 자고 있어요. 루카스, 시트 네가 공유할래?"),
(L, "Ya está. Primero, el tipo de cambio. ¿Cuál usamos?", "됐어요. 먼저 환율이요. 얼마로 할까요?"),
(E, "Cambia todos los días. Para redondear, pongan veinte pesos por euro. Luego ajustamos.", "날마다 바뀌어요. 계산하기 쉽게 1유로에 20페소로 두세요. 나중에 조정하죠."),
(A, "Una pregunta antes. Nuestro precio está en euros. Si el peso se cae, ¿quién lo paga?", "그 전에 질문 하나요. 우리 가격은 유로예요. 페소가 떨어지면 누가 손해를 보죠?"),
(E, "Doña Alejandra. Ella compra en euros y vende en pesos. El riesgo cambiario es suyo.", "알레한드라 여사요. 유로로 사서 페소로 파니까요. 환율 위험은 그분 몫이에요."),
(L, "Eso también puede ser un problema para nosotros. Si el peso se cae un diez por ciento, la torre le sale un diez por ciento más cara.", "그건 우리한테도 문제가 될 수 있어요. 페소가 10% 떨어지면 그쪽엔 아파트 타일이 10% 비싸지는 거니까요."),
(R, "Y nos pedirá descuento. La conozco poco, pero ya lo sé: todo acaba en descuento.", "그럼 우리한테 할인해 달라고 하겠지. 잘 모르는 사람이지만 이건 알아. 결국 다 할인 얘기로 끝나."),
(E, "O se cubre. Los importadores serios compran euros a futuro con su banco. Pregúntenle si lo hace.", "아니면 헤지를 하죠. 제대로 된 수입업자는 은행에서 선물환으로 유로를 사 둬요. 그렇게 하는지 물어보세요."),
(A, "Lo apunto: preguntar a Alejandra por la cobertura del tipo de cambio.", "적어 둘게요. 알레한드라에게 환헤지 여부 물어보기."),
(R, "Bien. Volvamos al número. Veinte pesos por euro. Entonces, quince noventa y cuatro por veinte...", "좋아. 숫자로 돌아가자. 1유로에 20페소. 그럼 15.94 곱하기 20은…"),
(L, "Sale a trescientos dieciocho pesos con ochenta el metro cuadrado. Ese es nuestro precio DAP en pesos.", "㎡당 318페소 80센타보가 나와요. 그게 페소로 환산한 우리 DAP 가격이에요."),
(E, "Ahora súmenle lo del despacho. Por contenedor, entre mis honorarios, la prevalidación, el DTA y las maniobras del lado del importador, calculen unos ocho mil quinientos pesos.", "이제 통관 비용을 더하세요. 컨테이너당 제 수수료, 사전 검증비, DTA, 수입자 쪽 하역 작업비를 합쳐 8,500페소 정도로 잡으세요."),
(A, "¿Por contenedor? Lucas, ¿cuántos metros cabían en uno?", "컨테이너당이요? 루카스, 하나에 몇 ㎡ 들어가죠?"),
(L, "Mil trescientos. Ocho mil quinientos entre mil trescientos... seis pesos con cincuenta y cuatro el metro.", "1,300이요. 8,500 나누기 1,300은… ㎡당 6페소 54센타보."),
(R, "O sea, treinta y tres céntimos de euro. Menos de lo que pensaba.", "그러니까 33유로센트네. 생각보다 적어."),
(E, "Porque su baldosa es pesada, pero no es cara por kilo. Si fueran relojes suizos, la cuenta sería otra.", "타일이 무겁긴 해도 킬로당 값은 비싸지 않으니까요. 스위스 시계였다면 계산이 달랐겠죠."),
(L, "Entonces el total queda en trescientos veinticinco pesos con treinta y cuatro el metro, puesto en bodega, antes de IVA.", "그럼 합계는 ㎡당 325페소 34센타보예요. 창고 도착 기준, 부가세 전이요."),
(A, "En euros, unos dieciséis con veintisiete.", "유로로는 16.27유로쯤이네요."),
(R, "¿Y con IVA?", "부가세 포함하면?"),
(E, "Unos trescientos setenta y siete pesos. Pero ya quedamos en que el IVA no es costo.", "377페소쯤이요. 하지만 부가세는 비용이 아니라고 이미 합의했잖아요."),
(R, "Lo sé, lo sé. Soy financiero: el IVA me da miedo aunque no sea mío.", "알아요, 알아요. 재무 담당이라 그래요. 내 돈이 아니어도 부가세는 무서워요."),
(L, "Y para las dos torres: cuarenta mil metros por trescientos veinticinco... suma unos trece millones de pesos.", "그리고 두 동 전체로는 4만㎡ 곱하기 325… 합계 1,300만 페소쯤이에요."),
(A, "Trece millones de pesos. Dicho así, parece que estamos comprando el hotel entero.", "1,300만 페소. 그렇게 말하니까 호텔을 통째로 사는 것 같네요."),
(E, "(ríe) En pesos todo suena a lotería. Unos seiscientos cincuenta mil euros, ¿no?", "(웃으며) 페소로 말하면 뭐든 복권 당첨금 같죠. 유로로는 65만 정도죠?"),
(R, "Seiscientos cincuenta mil, sí. El anticipo del treinta por ciento va sobre nuestra factura, no sobre esto: unos ciento noventa y un mil euros. Y las terrazas antideslizantes van aparte: el precio os lo paso mañana.", "65만, 맞아요. 30% 선수금은 이 금액이 아니라 우리 송장 기준이에요. 19만 1천 유로쯤. 그리고 미끄럼 방지 테라스분은 별도야. 가격은 내일 알려 줄게."),
(L, "Ramón, ¿lo ves claro?", "라몬, 이해되죠?"),
(R, "Clarísimo. La pregunta es la de siempre: ¿y los italianos?", "아주 분명해. 질문은 늘 같아. 이탈리아 쪽은?"),
(E, "Ahí no les puedo ayudar. Hay clientes cuyos números no salen de esta oficina. Y los de ustedes tampoco van a salir.", "그건 도와드릴 수 없어요. 숫자가 이 사무실 밖으로 나가지 않는 고객들이 있어요. 여러분의 숫자도 마찬가지로 안 나갈 거고요."),
(A, "Nos parece perfecto. Preferimos un agente que no hable de más.", "그게 좋아요. 말이 많지 않은 관세사가 더 좋거든요."),
(E, "Lo que sí les digo es de sentido común: el que viene de Italia pasa más días en el mar, y si el barco transborda, más todavía.", "상식선에서 말씀드릴 수 있는 건 이거예요. 이탈리아에서 오는 쪽은 바다에서 며칠 더 보내고, 배가 환적까지 하면 더 길어지죠."),
(L, "Alejandra nos dijo ayer que los italianos, puestos en bodega, le salen por encima de nuestro número. Y dicen que tienen los hornos llenos con un proyecto saudí.", "알레한드라가 어제 그러더군요. 이탈리아 쪽은 창고 도착 기준으로 우리 숫자보다 비싸게 나온대요. 그리고 사우디 프로젝트 때문에 가마가 꽉 찼다는 소문도 있고요."),
(R, "Si eso es verdad, estamos por debajo. Y con cuatro semanas menos de plazo.", "그게 사실이면 우리가 더 싼 거네. 납기도 4주 짧고."),
(E, "Y el plazo también es dinero. Una obra parada cuesta más que cualquier arancel.", "납기도 돈이에요. 공사가 멈추면 어떤 관세보다 비싸게 먹혀요."),
(A, "¿Y si hay retrasos en el puerto? ¿Quién paga el almacenaje?", "항구에서 지연되면요? 보관료는 누가 내죠?"),
(E, "Depende. Si el contenedor llega y yo no tengo los papeles, lo paga el importador. Si llega y los papeles vienen mal, también lo paga el importador... pero después se lo reclama a ustedes.", "경우에 따라 달라요. 컨테이너가 왔는데 제게 서류가 없으면 수입자가 내요. 서류가 잘못 왔어도 수입자가 내죠… 하지만 나중에 여러분한테 청구해요."),
(L, "O sea, que los papeles son responsabilidad nuestra, aunque el despacho no lo sea.", "그러니까 통관은 우리 몫이 아니어도, 서류는 우리 책임이라는 거군요."),
(E, "Exacto. Por eso el borrador. Y por eso, una cosa más.", "바로 그거예요. 그래서 초안이 필요한 거고요. 그리고 하나 더 있어요."),
(R, "¿Otra cosa? Aquí son las siete y media...", "또요? 여기 7시 반인데…"),
(E, "Una sola, licenciado. Si pagan el anticipo el treinta de abril, ¿para cuándo habrá salido el primer contenedor de Valencia?", "딱 하나예요, 선생님. 4월 30일에 선수금을 내면, 첫 컨테이너는 언제쯤 발렌시아를 떠나 있을까요?"),
(L, "Seis semanas después del anticipo. Hacia el diez de junio habrá salido.", "선수금 받고 6주 뒤니까, 6월 10일쯤이면 출항했을 거예요."),
(E, "Y con dieciocho o veinte días de mar, para principios de julio habrá llegado a Altamira.", "그리고 항해가 18일에서 20일이니까, 7월 초면 알타미라에 도착해 있겠군요."),
(A, "Justo antes de lo peor de la temporada de huracanes, ¿no?", "허리케인 철이 본격적으로 오기 직전이네요, 그렇죠?"),
(E, "(se encoge de hombros) Los huracanes no leen el calendario, licenciada. Pero sí, julio todavía suele estar tranquilo.", "(어깨를 으쓱하며) 허리케인은 달력을 안 읽어요, 선생님. 하지만 맞아요, 7월은 대개 아직 잠잠해요."),
(R, "Me voy a casa con esa frase. Buenas noches a todos.", "그 말 들고 집에 갈게요. 다들 잘 자요."),

("#", "Escena 3 · 12:15 · Despacho de Ernesto — la etiqueta", "장면 3 · 낮 12시 15분 · 에르네스토의 사무실 — 라벨"),
(None, "Ramón se desconecta. Maru trae más café. Ernesto saca de un armario una caja de azulejos de otra marca y la pone sobre la mesa.", "라몬이 연결을 끊는다. 마루가 커피를 더 가져온다. 에르네스토가 캐비닛에서 다른 브랜드의 타일 상자를 꺼내 탁자 위에 놓는다."),
(E, "Ahora, lo que no se ve en la hoja de cálculo. ¿Ya resolvieron su etiqueta?", "이제 스프레드시트에 안 보이는 얘기를 하죠. 라벨 문제는 해결했나요?"),
(L, "Nuria, nuestra diseñadora, nos manda hoy el diseño de una etiqueta lateral adicional. Nuestras cajas ya dicen «Hecho en España», pero les faltan el nombre, el domicilio y el RFC del importador.", "저희 디자이너 누리아가 오늘 추가 측면 라벨 디자인을 보내 줘요. 저희 상자에 '스페인산' 표시는 이미 있는데, 수입자 이름과 주소, RFC가 빠져 있거든요."),
(E, "Miren esta caja. Es de un cliente cuyo nombre no importa. Fíjense en el costado.", "이 상자를 보세요. 이름은 중요하지 않은 어느 고객 거예요. 옆면을 보세요."),
(A, "«Hecho en...», el importador, su RFC, el domicilio, el contenido en metros cuadrados, las medidas...", "'제조국…', 수입자, 그 회사의 납세자 번호(RFC), 주소, ㎡ 단위 내용량, 규격…"),
(E, "Eso es la información comercial obligatoria. Sin eso, la mercancía no se puede vender en México. Y muchas veces ni siquiera se puede despachar.", "그게 의무 상품 정보 표시예요. 그게 없으면 멕시코에서 팔 수 없어요. 통관조차 안 되는 경우도 많고요."),
(L, "¿Y si llega sin etiqueta?", "라벨 없이 도착하면요?"),
(E, "Hay una salida: se puede etiquetar aquí, en un almacén autorizado, con una unidad de verificación. Pero cuesta, tarda, y alguien tiene que abrir treinta contenedores caja por caja.", "방법은 있어요. 여기 허가받은 창고에서 검증 기관을 끼고 라벨을 붙일 수 있죠. 하지만 돈이 들고, 시간이 걸리고, 누군가 컨테이너 서른 개를 상자 하나하나 열어야 해요."),
(L, "¿Cuánto tiempo, más o menos?", "시간이 대략 얼마나 걸려요?"),
(E, "Con suerte, una semana por embarque. Sin suerte, dos. Y la obra, esperando.", "운이 좋으면 선적분마다 일주일. 운이 나쁘면 2주. 그동안 공사 현장은 기다리고요."),
(A, "¿Y la etiqueta va en cada caja o en el palé?", "라벨은 상자마다 붙여요, 아니면 팔레트에요?"),
(E, "En cada caja que pueda llegar al cliente final. Si la caja se vende sola, la etiqueta va en la caja.", "최종 소비자에게 갈 수 있는 상자마다요. 상자 단위로 팔리면 라벨은 상자에 붙여야 해요."),
(U, "(asomándose) Licenciado, perdón: le llaman los de Altamira por la línea dos.", "(문틈으로 고개를 내밀며) 변호사님, 죄송해요. 알타미라에서 2번으로 전화 왔어요."),
(E, "Dígales que ahorita les marco, Maru.", "아오리타 다시 건다고 전해 줘요, 마루."),
(U, "¿Ahorita-ahorita, o ahorita?", "'진짜 지금' 아오리타요, 아니면 그냥 아오리타요?"),
(E, "(riendo) Ahorita-ahorita. Tenemos visitas de España y hay que dar buen ejemplo.", "(웃으며) 진짜 지금. 스페인에서 손님이 오셨으니 모범을 보여야지."),
(A, "Imposible lo del almacén. Las cajas tienen que salir de Onda ya etiquetadas.", "창고에서 붙이는 건 말도 안 돼요. 상자는 온다에서 라벨을 붙인 채로 나가야 해요."),
(E, "Esa es la buena respuesta. Y otra cosa: el importador que aparece en la etiqueta es Garza Acabados, no ustedes.", "그게 정답이에요. 그리고 하나 더. 라벨에 나오는 수입자는 여러분이 아니라 가르사 아카바도스예요."),
(L, "Claro. Necesitaremos el RFC y el domicilio fiscal de Alejandra.", "그렇죠. 알레한드라 회사의 RFC와 세무상 주소가 필요하겠네요."),
(E, "Se los pido yo hoy mismo. Y en cuanto llegue el diseño de su diseñadora, me lo reenvían. Antes de imprimir nada, lo revisa una unidad de verificación mexicana.", "그건 제가 오늘 바로 받아 드릴게요. 그리고 디자이너분 시안이 오는 대로 저한테 전달해 주세요. 뭘 인쇄하기 전에 멕시코 검증 기관이 먼저 검토해야 해요."),
(A, "Gracias, licenciado. De verdad, no sé cómo pagarle tanta ayuda.", "고맙습니다, 선생님. 정말이지 이 많은 도움을 어떻게 갚아야 할지 모르겠어요."),
(E, "Fácil: con trabajo. Si estas torres salen bien, doña Alejandra me va a traer cien contenedores al año. Y yo, feliz.", "쉬워요. 일로 갚으면 돼요. 이 아파트 건이 잘되면 알레한드라 여사가 1년에 컨테이너 백 개는 들여올 거고, 그럼 저는 행복하죠."),
(L, "Licenciado, una última pregunta, ya no de números. ¿Por qué nos ayuda tanto?", "선생님, 마지막 질문이에요. 숫자 얘기는 아니고요. 왜 이렇게까지 도와주세요?"),
(E, "Porque en marzo usted me llamó a las seis de la mañana, hora de España, para pedir perdón por una factura que no era suya. Eso aquí se recuerda.", "3월에 당신이 스페인 시간으로 새벽 6시에 전화해서, 당신 것도 아닌 송장 때문에 사과했으니까요. 여기선 그런 걸 기억해요."),
(L, "No sabía que se notaba tanto.", "그렇게 티가 났는지 몰랐어요."),
(E, "Todo se nota, licenciado. Por teléfono, más.", "다 티가 나요, 선생님. 전화로는 더 그렇고요."),
(A, "(sonríe) Ya ves, Lucas. Al final, lo más importante no estaba en la hoja de cálculo.", "(미소 지으며) 거봐요, 루카스. 결국 제일 중요한 건 스프레드시트에 없었네요."),
(L, "Lo apunto: el arancel, el IVA, la etiqueta... y las llamadas a las seis de la mañana.", "적어 둘게요. 관세, 부가세, 라벨… 그리고 새벽 6시의 전화."),
(E, "Y una cosa más, ya de amigo: el sábado los Elizondo bautizan al nieto. Me dicen que ustedes están invitados.", "그리고 하나 더, 이건 친구로서 하는 말이에요. 토요일에 엘리손도 집안이 손자 세례식을 해요. 두 분도 초대받았다면서요."),
(A, "Sí, Alejandra nos lo dijo ayer. ¿Hay que llevar algo?", "네, 알레한드라가 어제 말해 줬어요. 뭘 가져가야 하나요?"),
(E, "Un regalito para el niño. Y cuidado con lo que dicen: allí van a estar todas las señoras de San Pedro.", "아기한테 줄 작은 선물이요. 그리고 말조심하세요. 산페드로의 사모님들이 다 모일 테니까요."),
(L, "¿Cuidado con qué?", "뭘 조심하라는 거죠?"),
(E, "(ríe) Con el español de España, licenciado. Hay palabras que allá son inocentes y aquí no tanto.", "(웃으며) 스페인의 스페인어요, 선생님. 거기선 순진한 말인데 여기선 그렇지 않은 단어들이 있거든요."),
(L, "¿Por ejemplo?", "예를 들면요?"),
(E, "Eso se lo explica Iván. Yo soy un señor serio. (le guiña un ojo a Maru)", "그건 이반이 설명해 줄 거예요. 저는 점잖은 사람이라서요. (마루에게 윙크한다)"),
(None, "Al salir, el sol de mediodía cae a plomo sobre la calle vacía. Amparo manda un mensaje a Nuria: «Etiqueta lateral: importador Garza Acabados + domicilio + RFC. Diseño a Ernesto antes de imprimir». Lucas guarda en la cartera la hoja con el número: 325,34 pesos.", "밖으로 나오자 한낮의 햇볕이 텅 빈 거리에 수직으로 내리꽂힌다. 암파로가 누리아에게 메시지를 보낸다. '측면 라벨: 수입자 가르사 아카바도스 + 주소 + RFC. 인쇄 전 에르네스토에게 시안.' 루카스는 숫자가 적힌 종이를 서류 가방에 넣는다. 325.34페소."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "성목요일, 반쯤 빈 몬테레이 도심. 루카스와 암파로는 6화에서 전화로 샘플을 구해 준 관세사 에르네스토 살리나스를 처음으로 직접 만난다. 에르네스토는 타일이 멕시코 항구에 닿아 '국산화'되기까지 내야 하는 네 가지(관세, 통관 수수료 DTA, 부가세, 관세사 수수료)를 칠판에 적고, 온다의 라몬과 화상으로 '창고 도착 원가'를 계산한다. 마지막으로 그는 다른 회사의 타일 상자를 꺼내 보여 주며, 숫자보다 무서운 문제인 라벨을 다시 짚는다.",
 "듣기 질문 ① 에르네스토가 말한 '국산화(nacionalizar)'란 무슨 뜻인가? 그리고 부가세가 '비용이 아닌' 이유는?",
 "듣기 질문 ② ㎡당 창고 도착 원가(부가세 전)는 페소와 유로로 각각 얼마인가? 두 동 전체로는?",
 "듣기 질문 ③ 라벨에 들어가야 할 정보는 무엇이며, 라벨에 적히는 수입자는 누구인가?",
]),
]

